    The breadcrumbs of an inner page: the parent pages (links where they have an href) separated by chevrons; the last entry is the current page and is not a link.
    Props (p): label, crumbs, landmarkLabel. -#}
{%- set v_label = (p.label ?? null) -%}
{%- set v_crumbs = (p.crumbs ?? null) -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- set v_last = og_sub(og_len(v_crumbs), 1) -%}
{%- set c_6 -%}
  {%- set c_5 -%}
    {%- for v_c in og_l(v_crumbs) %}
      {%- set v_i = loop.index0 -%}
      {%- set c_4 -%}
        {%- if og_t(og_lt(v_i, v_last)) %}
          {%- if og_t(og_get(v_c, ['href'])) %}
            {%- set c_1 -%}
              {{ og_text(og_get(v_c, ['name'])) }}
            {%- endset -%}
            {{ include('compose/Link.html.twig', {'href': og_url(og_s(og_get(v_c, ['href']))), 'variant': 'muted', 'size': 'sm', 'attrs': og_attrs(['data-slot', 'crumb']), 'children': c_1}, with_context = false) }}
          {%- else %}
            {%- set c_2 -%}
              {{ og_text(og_get(v_c, ['name'])) }}
            {%- endset -%}
            {{ include('compose/Inline.html.twig', {'attrs': og_attrs(['data-slot', 'crumb']), 'children': c_2}, with_context = false) }}
          {%- endif %}
          {{ include('icons/LucideIcon.html.twig', {'name': 'chevron-right', 'size': 16}, with_context = false) }}
        {%- else %}
          {%- set c_3 -%}
            {{ og_text(og_get(v_c, ['name'])) }}
          {%- endset -%}
          {{ include('compose/Inline.html.twig', {'class': 'font-medium text-foreground', 'attrs': og_attrs(['aria-current', 'page']), 'children': c_3}, with_context = false) }}
        {%- endif %}
      {%- endset -%}
      {{ include('compose/ListItem.html.twig', {'class': 'flex items-center gap-2', 'attrs': og_attrs(['data-slot', 'crumbs-row']), 'children': c_4}, with_context = false) }}
    {%- endfor %}
  {%- endset -%}
  {{ include('compose/List.html.twig', {'class': 'm-0 flex list-none flex-wrap items-center gap-2 p-0 text-sm text-muted-foreground', 'children': c_5}, with_context = false) }}
{%- endset -%}
{{ include('compose/Block.html.twig', {'tag': 'nav', 'attrs': og_attrs(['aria-label', og_coalesce([v_landmarkLabel, v_label]), 'data-slot', 'crumbs']), 'children': c_6}, with_context = false) }}
